import type { VivaQuestion } from './types';

// The viva bank of Class 12 Accountancy (CBSE 2025-26): questions an examiner may ask about the project and the course, each with a short model answer. Format in types.ts; checked by validate.ts.
const VIVA_12: VivaQuestion[] = [
  // -------------------------------------------------------------------------------------------------------------
  // The project: the financial statement analysis of a company.
  // -------------------------------------------------------------------------------------------------------------
  { id: 'v12-001', topicId: 'project', options: ['fsa'], difficulty: 'easy',
    question: "What is the topic of your project?",
    answer: "I analysed the financial statements of a listed company for two years using two aspects, for example comparative and common size statements and accounting ratios. Name the company, the two years and the two aspects exactly as they appear on the cover of your file." },
  { id: 'v12-002', topicId: 'project', options: ['fsa'], difficulty: 'medium',
    question: "Why did you choose this company?",
    answer: "Give a true reason: for example, I use the company's products and wanted to see how it earns, and its annual report is easy to get from its website. A company whose business is simple to understand makes the analysis easier to explain." },
  { id: 'v12-003', topicId: 'project', options: ['fsa'], difficulty: 'easy',
    question: "Where did you get the company's financial statements from?",
    answer: "I downloaded the latest annual report from the investor relations section of the company's website and checked it against the copy filed on the stock exchange's website (BSE or NSE). I used the audited statements in the report, not figures from a news story." },
  { id: 'v12-004', topicId: 'project', options: ['fsa'], difficulty: 'medium',
    question: "Why should the company you analyse be a listed company?",
    answer: "A listed company must publish its audited financial statements every year and file them with the stock exchange, so the figures are public, reliable and in the format I studied. An unlisted company's statements are rarely available to a student." },
  { id: 'v12-005', topicId: 'project', options: ['fsa'], difficulty: 'easy',
    question: "What is an annual report?",
    answer: "It is the document a company publishes every year for its shareholders. It contains the directors' report, management discussion and analysis, the auditor's report, and the audited financial statements with their notes." },
  { id: 'v12-006', topicId: 'project', options: ['fsa'], difficulty: 'easy',
    question: "What is the difference between standalone and consolidated financial statements?",
    answer: "Standalone statements show the company alone as a single legal entity, while consolidated statements combine the parent company with its subsidiaries as if they were one economic unit. The two can differ a great deal when the company has large subsidiaries." },
  { id: 'v12-007', topicId: 'project', options: ['fsa'], difficulty: 'medium',
    question: "Did you use the standalone or the consolidated statements, and why?",
    answer: "Give your true choice, for example: I used the standalone statements because they show the company itself and are closest to the format in my textbook. Whatever the choice, I used the same basis for both years so that the comparison is fair." },
  { id: 'v12-008', topicId: 'project', options: ['fsa'], difficulty: 'medium',
    question: "Which two aspects did you choose for your analysis, and why?",
    answer: "Name your two and give a reason, for example: I chose comparative and common size statements to see how each item changed and its weight in the total, and accounting ratios to judge liquidity, solvency, efficiency and profitability. Together they show both the size of the changes and what the changes mean." },
  { id: 'v12-009', topicId: 'project', options: ['fsa'], difficulty: 'medium',
    question: "Why did you analyse two years and not just one?",
    answer: "A single year's figures have no standard to compare with, so I compared the current year with the previous year to see whether the position improved or worsened. The annual report gives both years side by side, so the figures are on the same basis." },
  { id: 'v12-010', topicId: 'project', options: ['fsa'], difficulty: 'easy',
    question: "How did you round the figures in your project?",
    answer: "I took the figures as the company reported them, in ₹ crore or ₹ lakh, and rounded every percentage and ratio to two decimal places. I rounded only the final results, not the figures in between, and stated the unit and the rule in my conventions." },
  { id: 'v12-011', topicId: 'project', options: ['fsa'], difficulty: 'easy',
    question: "What is an operating segment?",
    answer: "It is a part of a company that earns revenue and incurs expenses, whose results the chief operating decision maker reviews regularly to decide how to allocate resources and judge performance, and for which separate financial information is available. Ind AS 108 defines it this way." },
  { id: 'v12-012', topicId: 'project', options: ['fsa'], difficulty: 'easy',
    question: "What does the segment information in an annual report show?",
    answer: "It shows the revenue, the result (profit or loss) and usually the assets and liabilities of each operating segment, and often the revenue by geographical area. It tells a reader which business earns the most and which is growing or struggling." },
  { id: 'v12-013', topicId: 'project', options: ['fsa'], difficulty: 'easy',
    question: "Which standard governs segment reporting by Indian listed companies?",
    answer: "Ind AS 108, Operating Segments. It requires segments to be identified in the same way the management itself reviews the business." },
  { id: 'v12-014', topicId: 'project', options: ['fsa'], difficulty: 'easy',
    question: "Where did you find the segment information in the annual report?",
    answer: "It is in a note to the financial statements titled segment information or operating segments, usually near the end of the notes. When a report has both standalone and consolidated statements, Ind AS 108 requires it only in the consolidated statements, so I looked there." },
  { id: 'v12-015', topicId: 'project', options: ['fsa'], difficulty: 'complex',
    question: "When must an operating segment be reported separately?",
    answer: "Under Ind AS 108 a segment is reportable when its revenue (external and inter-segment) is 10% or more of the combined revenue of all operating segments, its profit or loss is 10% or more of the greater of the combined profits and the combined losses, or its assets are 10% or more of the combined assets. If the reportable segments together give less than 75% of the company's external revenue, more segments must be reported until they reach 75%." },
  { id: 'v12-016', topicId: 'project', options: ['fsa'], difficulty: 'complex',
    question: "What did the segment report of your company tell you?",
    answer: "Answer from your own file, for example: the home care segment gave 70% of revenue, but the personal care segment grew faster and earned a higher profit on the assets it used. Then say what this means for the company's future, not only the figures." },
  { id: 'v12-017', topicId: 'project', options: ['fsa'], difficulty: 'complex',
    question: "What was the most important finding of your analysis?",
    answer: "State one finding with its figures and its meaning, for example: the current ratio fell from 1.6:1 to 1.2:1 because short-term borrowings rose, so liquidity weakened though current assets still cover current liabilities. Then say what the company could do about it." },
  { id: 'v12-018', topicId: 'project', options: ['fsa'], difficulty: 'complex',
    question: "What did you conclude about the company?",
    answer: "Give a balanced conclusion drawn from your figures, for example: revenue grew by 12% and the net profit ratio stayed near 9%, so profitability is steady, but the debt-equity ratio rose from 0.4:1 to 0.7:1, so the company now relies more on borrowed funds. Mention both a strength and a concern." },
  { id: 'v12-019', topicId: 'project', options: ['fsa'], difficulty: 'medium',
    question: "What are the limitations of your analysis?",
    answer: "I studied only two years of one company, the figures are historical and not adjusted for inflation, and other companies follow different accounting policies, which makes comparison harder. Factors that money cannot measure, such as the quality of management, do not appear in the statements at all." },
  { id: 'v12-020', topicId: 'project', options: ['fsa'], difficulty: 'complex',
    question: "Did you compare your company with another company or with the industry?",
    answer: "If you did, say which company and what the comparison showed. If not, say honestly that I compared two years of one company, and that comparing the ratios with a competitor or the industry average would make my judgement stronger." },
  { id: 'v12-021', topicId: 'project', options: ['fsa'], difficulty: 'easy',
    question: "What are the parts of your project file?",
    answer: "The certificate, the acknowledgement, the index, an introduction to the company, the analysis of the two aspects with workings, the conclusion, and the bibliography." },
  { id: 'v12-022', topicId: 'project', options: ['fsa'], difficulty: 'easy',
    question: "What does the certificate in your project file say?",
    answer: "It states that the student named on it did the project during the session 2025-26 as part of the CBSE syllabus. It is signed by the subject teacher and usually by the principal and the external examiner." },
  { id: 'v12-023', topicId: 'project', options: ['fsa'], difficulty: 'easy',
    question: "What did you write in the introduction to the company?",
    answer: "I wrote the company's name, when it was incorporated, where its registered office is, its main products or services, its business segments, the stock exchanges where its shares are listed, and the two years I analysed." },
  { id: 'v12-024', topicId: 'project', options: ['fsa'], difficulty: 'easy',
    question: "What is a bibliography, and what is in yours?",
    answer: "It lists the sources I used, so that anyone can find them again. Mine lists the company's annual reports with their years and web addresses, the stock exchange website, and my Accountancy textbook." },
  { id: 'v12-025', topicId: 'project', options: ['fsa'], difficulty: 'easy',
    question: "Why does a project file have an acknowledgement?",
    answer: "To thank, briefly and honestly, the people who helped with the project, such as the subject teacher, the principal and family members." },
  { id: 'v12-026', topicId: 'project', options: ['fsa'], difficulty: 'medium',
    question: "How did you prepare the comparative statement in your project?",
    answer: "I placed the two years' figures side by side, found the absolute change by taking the previous year from the current year, and found the percentage change by dividing that change by the previous year's figure and multiplying by 100." },
  { id: 'v12-027', topicId: 'project', options: ['fsa'], difficulty: 'complex',
    question: "The company's statements follow Ind AS; how did you handle headings that differ from your textbook?",
    answer: "Listed companies prepare statements under Ind AS, so some headings differ from the textbook format, for example Other Equity instead of Reserves and Surplus, and an extra section for other comprehensive income. I placed each item under the nearest textbook head and stated this in my conventions." },
  { id: 'v12-028', topicId: 'project', options: ['fsa'], difficulty: 'medium',
    question: "Why did you need to read the notes to the financial statements?",
    answer: "The balance sheet and the statement of profit and loss give only totals, and the notes give the details behind them. I needed the notes for figures such as long-term borrowings, inventories, trade receivables and finance costs." },
  { id: 'v12-029', topicId: 'project', options: ['fsa'], difficulty: 'medium',
    question: "How did you make sure the figures in your project were correct?",
    answer: "I checked that the balance sheet totals agreed for both years, worked every ratio again from the source figures, and matched my totals with those in the annual report. A teacher or a classmate also checked a few workings." },
  { id: 'v12-030', topicId: 'project', options: ['fsa'], difficulty: 'medium',
    question: "What is the difference between the auditor's report and the financial statements?",
    answer: "The financial statements are prepared by the company's management, while the auditor's report is an independent opinion on whether they give a true and fair view. I used audited statements so that my figures are reliable." },
  { id: 'v12-031', topicId: 'project', options: ['fsa'], difficulty: 'medium',
    question: "If you chose the cash flow statement as an aspect, why?",
    answer: "Give a true reason, for example: a company can show a profit and still be short of cash, and the cash flow statement shows whether its operations really produce cash and how it paid for its investments. It also shows how much the company borrowed or repaid during the year." },
  { id: 'v12-032', topicId: 'project', options: ['fsa'], difficulty: 'medium',
    question: "What would you do differently if you did this project again?",
    answer: "Give an honest answer, for example: I would take three years instead of two and compare the company with a competitor. I would also read the notes earlier, because some figures I needed were only there." },
  { id: 'v12-033', topicId: 'project', options: ['fsa'], difficulty: 'easy',
    question: "How did you plan the time for your project?",
    answer: "Give a true account, for example: about six weeks, with the first week spent choosing the company and downloading the reports, the next three on the statements and workings, and the last two on the conclusion, checking and binding." },
  { id: 'v12-034', topicId: 'project', options: ['fsa'], difficulty: 'easy',
    question: "What does the company you studied do, and in which industry is it?",
    answer: "Describe its business in one or two sentences, for example: it makes and sells packaged foods across India and abroad, so it belongs to the fast-moving consumer goods industry. Mention its main segments if it has more than one." },
  // -------------------------------------------------------------------------------------------------------------
  // The project: the Computerised Accounting practical file.
  // -------------------------------------------------------------------------------------------------------------
  { id: 'v12-035', topicId: 'project', options: ['computerised'], difficulty: 'easy',
    question: "What does the SUM function do in a spreadsheet?",
    answer: "It adds all the numbers in a range of cells; for example, =SUM(B2:B10) adds the values in cells B2 to B10. I used it to total the gross and net pay in my payroll sheet." },
  { id: 'v12-036', topicId: 'project', options: ['computerised'], difficulty: 'medium',
    question: "How does the IF function work, and where did you use it?",
    answer: "IF tests a condition and returns one value when it is true and another when it is false. For example, =IF(C2>50000,C2*10%,C2*5%) gives a bonus of 10% of the pay in C2 when it is above ₹50,000, and 5% of it otherwise." },
  { id: 'v12-037', topicId: 'project', options: ['computerised'], difficulty: 'medium',
    question: "Why is a rate kept in one cell referred to as $B$2 and not B2 in a schedule?",
    answer: "A relative reference such as B2 changes when a formula is copied to another cell, while an absolute reference such as $B$2 stays fixed. I kept the DA rate in one cell and referred to it absolutely, so every employee's formula used the same rate." },
  { id: 'v12-038', topicId: 'project', options: ['computerised'], difficulty: 'easy',
    question: "What do VLOOKUP and HLOOKUP do?",
    answer: "VLOOKUP looks for a value in the first column of a table and returns the value from a stated column of the same row, for example an employee's basic pay from the employee code. HLOOKUP does the same across rows: it looks in the first row of a table and returns the value from a stated row of the same column." },
  { id: 'v12-039', topicId: 'project', options: ['computerised'], difficulty: 'complex',
    question: "How did you prepare a loan repayment schedule in a spreadsheet?",
    answer: "I found the equal monthly instalment with =PMT(annual rate/12, number of months, -loan amount). Each month the interest is the opening balance times the monthly rate, the principal repaid is the instalment less that interest, and the closing balance falls until it reaches zero in the last month." },
  { id: 'v12-040', topicId: 'project', options: ['computerised'], difficulty: 'easy',
    question: "What do the SLN and DB functions calculate?",
    answer: "SLN(cost, salvage, life) gives the yearly depreciation by the straight line method, and DB(cost, salvage, life, period) gives the depreciation of a given year by the fixed rate on diminishing balance. For example, =SLN(100000,10000,5) gives ₹18,000 a year." },
  { id: 'v12-041', topicId: 'project', options: ['computerised'], difficulty: 'complex',
    question: "How does the depreciation from SLN differ from DB over an asset's life?",
    answer: "SLN charges the same amount every year, while DB charges more in the early years and less later because it applies a fixed rate to a falling book value. SLN brings the asset exactly to its salvage value at the end of its life, while DB, whose rate is rounded, brings it only close to it." },
  { id: 'v12-042', topicId: 'project', options: ['computerised'], difficulty: 'easy',
    question: "What does your payroll sheet show?",
    answer: "For each employee it shows the basic pay, dearness allowance, house rent allowance, gross salary, provident fund deduction and net salary. Every figure after the basic pay is worked by a formula from the basic pay and the rates." },
  { id: 'v12-043', topicId: 'project', options: ['computerised'], difficulty: 'medium',
    question: "How is the net salary worked out in your payroll sheet?",
    answer: "Gross salary is basic pay plus DA plus HRA, and net salary is gross salary less deductions such as provident fund. For example, with basic pay of ₹20,000, DA at 40% and HRA at 10%, the gross is ₹30,000, and with PF at 12% of basic (₹2,400) the net salary is ₹27,600." },
  { id: 'v12-044', topicId: 'project', options: ['computerised'], difficulty: 'easy',
    question: "Why did you use charts in your practical file, and which ones?",
    answer: "A chart shows a comparison at a glance. I used a column chart to compare expenses month by month and a pie chart to show the share of each expense in the total." },
  { id: 'v12-045', topicId: 'project', options: ['computerised'], difficulty: 'easy',
    question: "How do you create a company in an accounting package?",
    answer: "I entered the company's name, address, the financial year beginning on 1 April 2025, the date from which books begin, and the base currency, and saved it. Then I turned on the features I needed, such as GST and inventory." },
  { id: 'v12-046', topicId: 'project', options: ['computerised'], difficulty: 'easy',
    question: "What are groups and ledgers in an accounting package?",
    answer: "A ledger is an individual account such as Cash, Sales or a customer's account, and a group is a collection of similar ledgers such as Current Assets or Indirect Expenses. The group decides where the ledger's balance appears in the final statements." },
  { id: 'v12-047', topicId: 'project', options: ['computerised'], difficulty: 'medium',
    question: "Which voucher types did you use in the accounting package, and for what?",
    answer: "Receipt vouchers for money received, payment vouchers for money paid, contra vouchers for transfers between cash and bank, sales and purchase vouchers for trading transactions, and journal vouchers for adjustments such as depreciation or outstanding expenses." },
  { id: 'v12-048', topicId: 'project', options: ['computerised'], difficulty: 'easy',
    question: "How did you get the trial balance, profit and loss account and balance sheet from the package?",
    answer: "The package prepares them from the ledgers as soon as the vouchers are entered. I opened them from the reports menu, checked that the trial balance agreed, and printed them for my file." },
  { id: 'v12-049', topicId: 'project', options: ['computerised'], difficulty: 'medium',
    question: "How did you set up GST in the accounting package?",
    answer: "I turned on GST in the company's features and entered the GSTIN and the state. Then I set the GST rates on the stock items or the sales and purchase ledgers, and created ledgers for input and output CGST, SGST and IGST under Duties and Taxes." },
  { id: 'v12-050', topicId: 'project', options: ['computerised'], difficulty: 'easy',
    question: "How did you prepare a bank reconciliation statement in a spreadsheet?",
    answer: "I started from the balance as per the cash book, added items such as cheques issued but not yet presented, and deducted items such as cheques deposited but not yet credited, each total worked with SUM. The last cell, the balance as per the pass book, is a formula, so it updates when any item changes." },
  { id: 'v12-051', topicId: 'project', options: ['computerised'], difficulty: 'easy',
    question: "What is codification of accounts, and why is it needed in a computerised system?",
    answer: "Codification gives each account head a code that shows its place in the hierarchy, for example 1000s for assets with 1100s for current assets within them. The codes keep every ledger under the right group, make entry quicker and errors fewer, and let the system sort and total the accounts for the reports." },
  { id: 'v12-052', topicId: 'project', options: ['computerised'], difficulty: 'complex',
    question: "Why use a spreadsheet for accounting work when an accounting package is available?",
    answer: "A spreadsheet is flexible: I can design my own schedules, such as depreciation or loan repayment, and see the effect of changing a rate at once. A package is better for routine double-entry records, because it posts vouchers to the ledgers and prepares the statements automatically." },
  { id: 'v12-053', topicId: 'project', options: ['computerised'], difficulty: 'medium',
    question: "What are the advantages and the main risk of computerised accounting?",
    answer: "It is fast and accurate, posts each voucher to all the ledgers at once, produces reports instantly and keeps records safely with backups. Its main risk is that a wrong voucher gives wrong statements, so correct entry and regular backups still matter." },
  { id: 'v12-054', topicId: 'project', options: ['computerised'], difficulty: 'complex',
    question: "In your payroll sheet, what happens if the DA rate changes from 40% to 42%?",
    answer: "Because every DA formula refers to the single rate cell absolutely, I change only that cell and the DA, gross salary and net salary of every employee update at once. For basic pay of ₹20,000 the DA rises from ₹8,000 to ₹8,400." },
  // -------------------------------------------------------------------------------------------------------------
  // Partnership: fundamentals.
  // -------------------------------------------------------------------------------------------------------------
  { id: 'v12-055', topicId: 'partnership-fundamentals', options: ['fsa', 'computerised'], difficulty: 'easy',
    question: "What is a partnership?",
    answer: "It is the relationship between persons who have agreed to share the profits of a business run by all of them, or by any of them acting for all. It is governed by the Indian Partnership Act, 1932." },
  { id: 'v12-056', topicId: 'partnership-fundamentals', options: ['fsa', 'computerised'], difficulty: 'easy',
    question: "What is the minimum and maximum number of partners in a firm?",
    answer: "The minimum is two. The maximum is 50, under Section 464 of the Companies Act, 2013 read with the Companies (Miscellaneous) Rules, 2014." },
  { id: 'v12-057', topicId: 'partnership-fundamentals', options: ['fsa', 'computerised'], difficulty: 'easy',
    question: "What is a partnership deed?",
    answer: "It is the written agreement among the partners that sets out the terms of the partnership. It covers matters such as capital, the profit-sharing ratio, interest on capital and drawings, salaries, and what happens on admission or retirement." },
  { id: 'v12-058', topicId: 'partnership-fundamentals', options: ['fsa', 'computerised'], difficulty: 'easy',
    question: "Which rules apply when there is no partnership deed?",
    answer: "Under the Indian Partnership Act, 1932, profits are shared equally, no interest is allowed on capital, no salary or commission is paid to a partner, and no interest is charged on drawings. Interest at 6% per annum is allowed on a loan given by a partner to the firm." },
  { id: 'v12-059', topicId: 'partnership-fundamentals', options: ['fsa', 'computerised'], difficulty: 'medium',
    question: "Is interest on a partner's loan a charge against profit or an appropriation of profit?",
    answer: "It is a charge against profit, so it is debited to the Profit and Loss Account and must be paid even if the firm makes a loss." },
  { id: 'v12-060', topicId: 'partnership-fundamentals', options: ['fsa', 'computerised'], difficulty: 'easy',
    question: "What is mutual agency in a partnership?",
    answer: "Each partner is an agent of the firm and of the other partners, so an act done by one partner in the normal course of business binds the firm and every partner." },
  { id: 'v12-061', topicId: 'partnership-fundamentals', options: ['fsa', 'computerised'], difficulty: 'easy',
    question: "What is the difference between fixed and fluctuating capital accounts?",
    answer: "Under fixed capitals, the capital account shows only capital brought in or permanently withdrawn, and drawings, interest, salary and share of profit go to a separate current account. Under fluctuating capitals all these items go to the capital account itself, so its balance changes every year." },
  { id: 'v12-062', topicId: 'partnership-fundamentals', options: ['fsa', 'computerised'], difficulty: 'easy',
    question: "What is the Profit and Loss Appropriation Account?",
    answer: "It is an extension of the Profit and Loss Account that shows how the net profit is divided among the partners. Interest on capital, salaries and commission to partners are debited, interest on drawings is credited, and the balance is shared in the profit-sharing ratio." },
  { id: 'v12-063', topicId: 'partnership-fundamentals', options: ['fsa', 'computerised'], difficulty: 'medium',
    question: "Why is a salary to a partner an appropriation and not an expense?",
    answer: "A partner is an owner of the firm, not an employee, so a salary to a partner is only a way of dividing the profit. It is shown in the Profit and Loss Appropriation Account and is allowed only when the deed provides for it." },
  { id: 'v12-064', topicId: 'partnership-fundamentals', options: ['fsa', 'computerised'], difficulty: 'complex',
    question: "The deed allows interest on capital, but the profit is less than the total interest; what happens?",
    answer: "Interest on capital is an appropriation, so it can be allowed only out of profit. The whole profit is then shared among the partners in the ratio of the interest due on their capitals, and if there is a loss no interest is allowed at all." },
  { id: 'v12-065', topicId: 'partnership-fundamentals', options: ['fsa', 'computerised'], difficulty: 'medium',
    question: "For what average period is interest charged when a partner draws the same amount at the end of every month for a year?",
    answer: "For 5.5 months, because the first drawing is outstanding for 11 months and the last for none, and the average of 11 and 0 is 5.5. If the drawings are at the start of each month the period is 6.5 months, and in the middle of each month it is 6 months." },
  { id: 'v12-066', topicId: 'partnership-fundamentals', options: ['fsa', 'computerised'], difficulty: 'complex',
    question: "Neha draws ₹5,000 at the start of every month for a year and interest on drawings is 10% per annum; what is the interest?",
    answer: "Total drawings are ₹60,000 and the average period is 6.5 months, so the interest is ₹60,000 × 10% × 6.5 ÷ 12 = ₹3,250." },
  { id: 'v12-067', topicId: 'partnership-fundamentals', options: ['fsa', 'computerised'], difficulty: 'medium',
    question: "What is a guarantee of profit to a partner?",
    answer: "It is a promise by the other partners, or by one of them, that a partner will get at least a fixed minimum amount of profit. Any shortfall is borne by the guaranteeing partners in the ratio they agreed, or in their profit-sharing ratio if no ratio was agreed." },
  { id: 'v12-068', topicId: 'partnership-fundamentals', options: ['fsa', 'computerised'], difficulty: 'complex',
    question: "Asha, Bimal and Chetan share profits 2:2:1, and Asha and Bimal guarantee Chetan at least ₹40,000, bearing any shortfall equally; how is a profit of ₹1,50,000 shared?",
    answer: "Chetan's share is ₹30,000, so the shortfall of ₹10,000 is borne ₹5,000 each by Asha and Bimal. Asha and Bimal get ₹55,000 each and Chetan gets ₹40,000, which adds up to ₹1,50,000." },
  { id: 'v12-069', topicId: 'partnership-fundamentals', options: ['fsa', 'computerised'], difficulty: 'complex',
    question: "A partner gets a commission of 10% of the net profit after charging that commission; if the profit before commission is ₹2,20,000, what is the commission?",
    answer: "The commission is ₹2,20,000 × 10 ÷ 110 = ₹20,000. This is right because the profit after commission is ₹2,00,000, and 10% of that is ₹20,000." },
  { id: 'v12-070', topicId: 'partnership-fundamentals', options: ['fsa', 'computerised'], difficulty: 'medium',
    question: "What are past adjustments, and how are they made?",
    answer: "They correct errors or omissions in accounts already closed, such as interest on capital that was not allowed. Instead of reopening the accounts, the net effect on each partner is worked out and put right by one adjusting entry between the partners' capital accounts." },
  // -------------------------------------------------------------------------------------------------------------
  // Goodwill.
  // -------------------------------------------------------------------------------------------------------------
  { id: 'v12-071', topicId: 'goodwill', options: ['fsa', 'computerised'], difficulty: 'easy',
    question: "What is goodwill?",
    answer: "Goodwill is the value of a firm's reputation and connections that enable it to earn more than the normal profit on its capital. It is an intangible asset, not a fictitious one." },
  { id: 'v12-072', topicId: 'goodwill', options: ['fsa', 'computerised'], difficulty: 'easy',
    question: "What factors affect the value of goodwill?",
    answer: "The nature of the business, its location, the efficiency of its management, the market situation such as little competition, special advantages like patents or licences, and the quality of its products. Anything that raises expected future profits raises goodwill." },
  { id: 'v12-073', topicId: 'goodwill', options: ['fsa', 'computerised'], difficulty: 'medium',
    question: "Why is goodwill valued when a partner is admitted or retires?",
    answer: "The profit-sharing ratio changes, so the partners who give up part of their future profits must be compensated by those who gain it. Goodwill measures the value of the reputation the old partners built." },
  { id: 'v12-074', topicId: 'goodwill', options: ['fsa', 'computerised'], difficulty: 'complex',
    question: "A firm's profits for three years are ₹80,000, ₹1,00,000 and ₹1,20,000; what is goodwill at two years' purchase of the average profit?",
    answer: "The average profit is ₹3,00,000 ÷ 3 = ₹1,00,000, so goodwill is ₹1,00,000 × 2 = ₹2,00,000." },
  { id: 'v12-075', topicId: 'goodwill', options: ['fsa', 'computerised'], difficulty: 'easy',
    question: "What is super profit?",
    answer: "Super profit is the amount by which the average profit exceeds the normal profit. Normal profit is the capital employed multiplied by the normal rate of return in that kind of business." },
  { id: 'v12-076', topicId: 'goodwill', options: ['fsa', 'computerised'], difficulty: 'complex',
    question: "Capital employed is ₹5,00,000, the normal rate of return is 10% and the average profit is ₹80,000; what is goodwill at three years' purchase of super profit?",
    answer: "Normal profit is ₹50,000, so super profit is ₹30,000 and goodwill is ₹30,000 × 3 = ₹90,000." },
  { id: 'v12-077', topicId: 'goodwill', options: ['fsa', 'computerised'], difficulty: 'medium',
    question: "How is goodwill found by capitalising the average profit?",
    answer: "Divide the average profit by the normal rate of return to get the capitalised value of the business, and subtract the actual capital employed. For example, ₹60,000 ÷ 12% = ₹5,00,000, and with capital employed of ₹4,20,000 the goodwill is ₹80,000." },
  { id: 'v12-078', topicId: 'goodwill', options: ['fsa', 'computerised'], difficulty: 'medium',
    question: "How is goodwill found by capitalising the super profit?",
    answer: "Goodwill equals super profit × 100 ÷ normal rate of return. For example, a super profit of ₹15,000 at a normal rate of 10% gives goodwill of ₹1,50,000." },
  { id: 'v12-079', topicId: 'goodwill', options: ['fsa', 'computerised'], difficulty: 'medium',
    question: "Why can a firm not open a Goodwill Account for its own goodwill?",
    answer: "Under AS 26 only purchased goodwill, for which the firm has paid, is recorded; goodwill generated by the firm itself is not recorded because it cannot be measured reliably. So on a change in partners, goodwill is adjusted through the partners' capital accounts instead." },
  { id: 'v12-080', topicId: 'goodwill', options: ['fsa', 'computerised'], difficulty: 'medium',
    question: "What is done with goodwill already shown in the books when a partner is admitted?",
    answer: "It is written off among the old partners in the old profit-sharing ratio, by debiting their capital accounts and crediting Goodwill Account." },
  { id: 'v12-081', topicId: 'goodwill', options: ['fsa', 'computerised'], difficulty: 'complex',
    question: "Kavya brings ₹1,00,000 as capital for a 1/4 share, and the old partners' capitals after all adjustments total ₹2,50,000; what is the firm's hidden goodwill?",
    answer: "Kavya's capital implies a total capital of ₹1,00,000 × 4 = ₹4,00,000, while the actual capital of all partners is ₹3,50,000. The difference of ₹50,000 is the firm's goodwill, and Kavya's share of it is ₹12,500." },
  // -------------------------------------------------------------------------------------------------------------
  // Change in profit-sharing ratio.
  // -------------------------------------------------------------------------------------------------------------
  { id: 'v12-082', topicId: 'change-in-profit-sharing-ratio', options: ['fsa', 'computerised'], difficulty: 'easy',
    question: "What is the sacrificing ratio?",
    answer: "It is the ratio in which the old partners give up their shares of profit in favour of another partner. Each partner's sacrifice is the old share minus the new share." },
  { id: 'v12-083', topicId: 'change-in-profit-sharing-ratio', options: ['fsa', 'computerised'], difficulty: 'easy',
    question: "What is the gaining ratio?",
    answer: "It is the ratio in which partners gain shares of profit, each gain being the new share minus the old share. It is used mainly on the retirement or death of a partner." },
  { id: 'v12-084', topicId: 'change-in-profit-sharing-ratio', options: ['fsa', 'computerised'], difficulty: 'complex',
    question: "Rohan and Sneha share profits 3:2 and decide to share equally; who sacrifices, and how much?",
    answer: "Rohan sacrifices 3/5 − 1/2 = 1/10 and Sneha gains 1/2 − 2/5 = 1/10. So Sneha compensates Rohan for goodwill on that 1/10 share." },
  { id: 'v12-085', topicId: 'change-in-profit-sharing-ratio', options: ['fsa', 'computerised'], difficulty: 'medium',
    question: "How is goodwill adjusted on a change in the profit-sharing ratio?",
    answer: "The gaining partner's capital account is debited and the sacrificing partner's capital account is credited with the value of the share gained or given up. No Goodwill Account is opened." },
  { id: 'v12-086', topicId: 'change-in-profit-sharing-ratio', options: ['fsa', 'computerised'], difficulty: 'medium',
    question: "Why are reserves and accumulated profits distributed before a change in the profit-sharing ratio?",
    answer: "They were earned while the old ratio applied, so they belong to the partners in the old ratio. If the partners prefer to keep them in the books, an adjusting entry between the gaining and sacrificing partners is passed instead." },
  { id: 'v12-087', topicId: 'change-in-profit-sharing-ratio', options: ['fsa', 'computerised'], difficulty: 'medium',
    question: "Why are assets and liabilities revalued on a change in the profit-sharing ratio?",
    answer: "The book values may differ from the current values, and any gain or loss up to the date of the change belongs to the partners in the old ratio. Revaluing ensures no partner gains or loses from a change in value that happened earlier." },
  { id: 'v12-088', topicId: 'change-in-profit-sharing-ratio', options: ['fsa', 'computerised'], difficulty: 'easy',
    question: "What is a Revaluation Account?",
    answer: "It is a nominal account that records the increase or decrease in the values of assets and liabilities on a reconstitution. Its profit or loss is shared by the old partners in the old ratio." },
  { id: 'v12-089', topicId: 'change-in-profit-sharing-ratio', options: ['fsa', 'computerised'], difficulty: 'medium',
    question: "On revaluation, a liability of ₹8,000 not in the books is found; how is it treated?",
    answer: "It is a loss on revaluation, so Revaluation Account is debited and the liability account credited with ₹8,000. The loss is shared by the old partners in the old ratio." },
  { id: 'v12-090', topicId: 'change-in-profit-sharing-ratio', options: ['fsa', 'computerised'], difficulty: 'medium',
    question: "How is a debit balance of the Profit and Loss Account treated on a reconstitution?",
    answer: "It is an accumulated loss, so it is written off to the old partners' capital accounts in the old ratio. Their capital accounts are debited and the Profit and Loss Account is credited." },
  { id: 'v12-091', topicId: 'change-in-profit-sharing-ratio', options: ['fsa', 'computerised'], difficulty: 'complex',
    question: "The Workmen Compensation Reserve is ₹30,000 and a claim of ₹12,000 is established; how is it treated on a reconstitution?",
    answer: "₹12,000 is transferred to a Workmen Compensation Claim (a liability), and the remaining ₹18,000 is distributed among the old partners in the old ratio." },
  // -------------------------------------------------------------------------------------------------------------
  // Admission of a partner.
  // -------------------------------------------------------------------------------------------------------------
  { id: 'v12-092', topicId: 'admission-of-a-partner', options: ['fsa', 'computerised'], difficulty: 'easy',
    question: "What rights does a new partner get on admission?",
    answer: "The right to a share in the future profits of the firm, the right to a share in its assets, and the right to take part in running the business." },
  { id: 'v12-093', topicId: 'admission-of-a-partner', options: ['fsa', 'computerised'], difficulty: 'easy',
    question: "Does the admission of a partner dissolve the firm?",
    answer: "No; it reconstitutes the partnership, so the old agreement ends and a new one begins, but the firm continues its business." },
  { id: 'v12-094', topicId: 'admission-of-a-partner', options: ['fsa', 'computerised'], difficulty: 'complex',
    question: "Amit and Bhavna share profits 3:2 and admit Charu for a 1/5 share taken from them in their old ratio; what is the new ratio?",
    answer: "The remaining 4/5 is shared 3:2, so Amit gets 12/25, Bhavna 8/25 and Charu 5/25. The new ratio is 12:8:5." },
  { id: 'v12-095', topicId: 'admission-of-a-partner', options: ['fsa', 'computerised'], difficulty: 'complex',
    question: "If Charu takes the 1/5 share equally from Amit and Bhavna, who shared 3:2, what is the new ratio?",
    answer: "Each gives up 1/10, so Amit gets 3/5 − 1/10 = 5/10, Bhavna 2/5 − 1/10 = 3/10 and Charu 2/10. The new ratio is 5:3:2." },
  { id: 'v12-096', topicId: 'admission-of-a-partner', options: ['fsa', 'computerised'], difficulty: 'medium',
    question: "Why is the sacrificing ratio needed on admission?",
    answer: "It shows how much of their profit share each old partner gives to the new partner. The premium for goodwill brought by the new partner is shared among the old partners in this ratio." },
  { id: 'v12-097', topicId: 'admission-of-a-partner', options: ['fsa', 'computerised'], difficulty: 'medium',
    question: "Dev is admitted for a 1/4 share and the firm's goodwill is valued at ₹1,20,000; how much premium does Dev bring?",
    answer: "Dev brings ₹1,20,000 × 1/4 = ₹30,000 as premium for goodwill. It is credited to the sacrificing partners' capital accounts in the sacrificing ratio." },
  { id: 'v12-098', topicId: 'admission-of-a-partner', options: ['fsa', 'computerised'], difficulty: 'medium',
    question: "How is the premium for goodwill treated when the new partner brings it in cash?",
    answer: "Cash is debited and Premium for Goodwill Account credited; then Premium for Goodwill Account is debited and the sacrificing partners' capital accounts are credited in the sacrificing ratio." },
  { id: 'v12-099', topicId: 'admission-of-a-partner', options: ['fsa', 'computerised'], difficulty: 'medium',
    question: "What is done when the new partner cannot bring the share of goodwill in cash?",
    answer: "The new partner's capital account (or current account) is debited with that share of goodwill, and the sacrificing partners' capital accounts are credited in the sacrificing ratio." },
  { id: 'v12-100', topicId: 'admission-of-a-partner', options: ['fsa', 'computerised'], difficulty: 'easy',
    question: "What entry records the capital brought in by a new partner?",
    answer: "Cash or Bank Account is debited and the new partner's capital account is credited." },
  { id: 'v12-101', topicId: 'admission-of-a-partner', options: ['fsa', 'computerised'], difficulty: 'complex',
    question: "The old partners' adjusted capitals total ₹3,00,000 and Esha is admitted for a 1/4 share; what capital should Esha bring to match?",
    answer: "The old partners hold 3/4, so the firm's total capital is ₹3,00,000 × 4/3 = ₹4,00,000. Esha should bring ₹4,00,000 × 1/4 = ₹1,00,000." },
  { id: 'v12-102', topicId: 'admission-of-a-partner', options: ['fsa', 'computerised'], difficulty: 'medium',
    question: "How are the old partners' capitals adjusted on the basis of the new partner's capital?",
    answer: "The firm's total capital is found from the new partner's capital and share, and each old partner's required capital is that total times the new share. Any surplus is withdrawn or credited to a current account, and any shortfall is brought in cash or debited to a current account." },
  // -------------------------------------------------------------------------------------------------------------
  // Retirement and death of a partner.
  // -------------------------------------------------------------------------------------------------------------
  { id: 'v12-103', topicId: 'retirement-and-death-of-a-partner', options: ['fsa', 'computerised'], difficulty: 'medium',
    question: "Why is the gaining ratio worked out on the retirement of a partner?",
    answer: "The continuing partners take over the retiring partner's share of profit, so they compensate the retiring partner for goodwill in the ratio in which they gain." },
  { id: 'v12-104', topicId: 'retirement-and-death-of-a-partner', options: ['fsa', 'computerised'], difficulty: 'medium',
    question: "Pooja, Qadir and Ravi share profits 3:2:1 and Ravi retires; what are the new ratio and the gaining ratio?",
    answer: "Unless agreed otherwise, Pooja and Qadir take over Ravi's share in their old ratio, so the new ratio is 3:2. The gaining ratio is also 3:2." },
  { id: 'v12-105', topicId: 'retirement-and-death-of-a-partner', options: ['fsa', 'computerised'], difficulty: 'complex',
    question: "The firm's goodwill is ₹90,000 and Ravi retires with a 1/6 share, Pooja and Qadir gaining 3:2; what is the goodwill entry?",
    answer: "Ravi's share is ₹90,000 × 1/6 = ₹15,000. Pooja's capital account is debited with ₹9,000 and Qadir's with ₹6,000, and Ravi's capital account is credited with ₹15,000." },
  { id: 'v12-106', topicId: 'retirement-and-death-of-a-partner', options: ['fsa', 'computerised'], difficulty: 'easy',
    question: "What is included in the amount due to a retiring partner?",
    answer: "The capital balance, the share of goodwill, the share of revaluation profit, reserves and accumulated profits, and any interest on capital or salary due. Drawings, interest on drawings and the share of any revaluation loss or accumulated loss are deducted." },
  { id: 'v12-107', topicId: 'retirement-and-death-of-a-partner', options: ['fsa', 'computerised'], difficulty: 'easy',
    question: "How may the amount due to a retiring partner be paid?",
    answer: "It may be paid in cash at once, transferred to the retiring partner's loan account and paid in instalments with interest, or paid partly in cash with the rest as a loan." },
  { id: 'v12-108', topicId: 'retirement-and-death-of-a-partner', options: ['fsa', 'computerised'], difficulty: 'medium',
    question: "What is a retiring partner entitled to if the amount due is not paid at once and there is no agreement?",
    answer: "Under Section 37 of the Indian Partnership Act, 1932, the retiring partner, or the legal representatives of a deceased partner, may choose either interest at 6% per annum on the amount due or the share of profit earned by using that amount." },
  { id: 'v12-109', topicId: 'retirement-and-death-of-a-partner', options: ['fsa', 'computerised'], difficulty: 'medium',
    question: "How is a deceased partner's share of profit up to the date of death found?",
    answer: "It is estimated from the end of the last accounting year to the date of death, on the basis of the previous year's profit (time basis) or of sales (turnover basis). It is debited to Profit and Loss Suspense Account and credited to the deceased partner's capital account." },
  { id: 'v12-110', topicId: 'retirement-and-death-of-a-partner', options: ['fsa', 'computerised'], difficulty: 'complex',
    question: "Gita had a 1/4 share and died on 30 June; the accounts close on 31 March and last year's profit was ₹1,20,000; what is Gita's share of profit up to death?",
    answer: "From 1 April to 30 June is three months, so the share is ₹1,20,000 × 3/12 × 1/4 = ₹7,500." },
  { id: 'v12-111', topicId: 'retirement-and-death-of-a-partner', options: ['fsa', 'computerised'], difficulty: 'easy',
    question: "To whom is the amount due to a deceased partner paid?",
    answer: "To the executors or legal representatives of the deceased partner, through the Deceased Partner's Executors Account." },
  { id: 'v12-112', topicId: 'retirement-and-death-of-a-partner', options: ['fsa', 'computerised'], difficulty: 'medium',
    question: "How does the accounting on the death of a partner differ from that on retirement?",
    answer: "The adjustments for goodwill, revaluation and reserves are the same, but death can occur at any time in the year. So the deceased partner's share of profit up to the date of death is worked out, and the amount due is transferred to the executors' account." },
  { id: 'v12-113', topicId: 'retirement-and-death-of-a-partner', options: ['fsa', 'computerised'], difficulty: 'easy',
    question: "In what ratio is the revaluation profit shared on the retirement of a partner?",
    answer: "In the old profit-sharing ratio, among all the partners including the retiring partner, because the change in value happened before the retirement." },
  // -------------------------------------------------------------------------------------------------------------
  // Dissolution of a partnership firm.
  // -------------------------------------------------------------------------------------------------------------
  { id: 'v12-114', topicId: 'dissolution-of-partnership', options: ['fsa', 'computerised'], difficulty: 'easy',
    question: "What is the difference between dissolution of partnership and dissolution of the firm?",
    answer: "Dissolution of partnership changes the relationship among the partners, as on admission or retirement, while the firm continues. Dissolution of the firm ends the relationship among all the partners, and the business is closed." },
  { id: 'v12-115', topicId: 'dissolution-of-partnership', options: ['fsa', 'computerised'], difficulty: 'easy',
    question: "In what ways can a firm be dissolved?",
    answer: "By agreement of all the partners, compulsorily (as when the business becomes illegal), on a contingency such as the end of its fixed term or the completion of its venture, by notice in a partnership at will, and by order of a court." },
  { id: 'v12-116', topicId: 'dissolution-of-partnership', options: ['fsa', 'computerised'], difficulty: 'easy',
    question: "What is a Realisation Account?",
    answer: "It is the account opened on dissolution to record the sale of assets and the payment of liabilities. Its balance is the profit or loss on realisation, shared by the partners in their profit-sharing ratio." },
  { id: 'v12-117', topicId: 'dissolution-of-partnership', options: ['fsa', 'computerised'], difficulty: 'medium',
    question: "Which balances are not transferred to the Realisation Account?",
    answer: "Cash and bank balances, because they are already cash; accumulated losses and fictitious assets, which go to the partners' capital accounts; and a partner's loan to the firm, which is paid separately. Partners' capital and current accounts and reserves are not transferred either." },
  { id: 'v12-118', topicId: 'dissolution-of-partnership', options: ['fsa', 'computerised'], difficulty: 'easy',
    question: "In what order are the firm's debts settled on dissolution?",
    answer: "Under Section 48 of the Indian Partnership Act, 1932, debts to outsiders are paid first, then partners' loans and advances, then partners' capitals. Any surplus left is shared in the profit-sharing ratio." },
  { id: 'v12-119', topicId: 'dissolution-of-partnership', options: ['fsa', 'computerised'], difficulty: 'easy',
    question: "What entry is passed when a partner takes over an asset on dissolution?",
    answer: "The partner's capital account is debited and the Realisation Account is credited with the agreed value of the asset." },
  { id: 'v12-120', topicId: 'dissolution-of-partnership', options: ['fsa', 'computerised'], difficulty: 'medium',
    question: "How are realisation expenses paid by a partner treated?",
    answer: "If the partner pays them on behalf of the firm, Realisation Account is debited and that partner's capital account credited. If the partner has agreed to bear them and pays them personally, no entry is passed." },
  { id: 'v12-121', topicId: 'dissolution-of-partnership', options: ['fsa', 'computerised'], difficulty: 'medium',
    question: "How is an unrecorded asset that is sold on dissolution treated?",
    answer: "It is a gain, so Cash or Bank Account is debited and Realisation Account credited with the amount realised." },
  { id: 'v12-122', topicId: 'dissolution-of-partnership', options: ['fsa', 'computerised'], difficulty: 'complex',
    question: "Creditors of ₹50,000 accept a machine valued at ₹40,000 and the rest in cash; what is recorded?",
    answer: "No entry is passed for the machine, because both the machine and the creditors are already in the Realisation Account. Only the cash paid, ₹10,000, is recorded by debiting Realisation Account and crediting Cash." },
  { id: 'v12-123', topicId: 'dissolution-of-partnership', options: ['fsa', 'computerised'], difficulty: 'complex',
    question: "Assets other than cash with a book value of ₹3,00,000 realise ₹2,70,000, liabilities of ₹1,00,000 are settled for ₹95,000 and expenses are ₹5,000; what is the result of realisation?",
    answer: "The debit side is ₹3,00,000 + ₹95,000 + ₹5,000 = ₹4,00,000 and the credit side is ₹1,00,000 + ₹2,70,000 = ₹3,70,000. So there is a loss on realisation of ₹30,000, shared by the partners in their profit-sharing ratio." },
  // -------------------------------------------------------------------------------------------------------------
  // Share capital.
  // -------------------------------------------------------------------------------------------------------------
  { id: 'v12-124', topicId: 'share-capital', options: ['fsa', 'computerised'], difficulty: 'easy',
    question: "What is a share?",
    answer: "A share is one of the equal units into which a company's capital is divided. Its holder is a part-owner of the company." },
  { id: 'v12-125', topicId: 'share-capital', options: ['fsa', 'computerised'], difficulty: 'easy',
    question: "How do preference shares differ from equity shares?",
    answer: "Preference shares carry a preferential right to dividend at a fixed rate and to the return of capital on winding up. Equity shares have no such preference, but they carry voting rights and the residual profit." },
  { id: 'v12-126', topicId: 'share-capital', options: ['fsa', 'computerised'], difficulty: 'medium',
    question: "What do authorised, issued, subscribed, called-up and paid-up capital mean?",
    answer: "Authorised capital is the maximum the company may issue under its memorandum, issued capital is the part offered for subscription, and subscribed capital is the part taken up. Called-up capital is the part of subscribed capital the company has asked for, and paid-up capital is the part actually received." },
  { id: 'v12-127', topicId: 'share-capital', options: ['fsa', 'computerised'], difficulty: 'easy',
    question: "What is minimum subscription?",
    answer: "It is the minimum amount that must be subscribed before shares can be allotted, which is 90% of the issue. If it is not received within the stated time, the company must refund all the application money." },
  { id: 'v12-128', topicId: 'share-capital', options: ['fsa', 'computerised'], difficulty: 'medium',
    question: "What can a company do when an issue is over-subscribed?",
    answer: "It may reject some applications and refund their money, allot shares pro rata to all applicants, or combine the two. Excess application money of pro-rata applicants is adjusted towards allotment, and towards calls if the terms allow." },
  { id: 'v12-129', topicId: 'share-capital', options: ['fsa', 'computerised'], difficulty: 'complex',
    question: "A company offers 10,000 shares, receives applications for 15,000 and allots pro rata to all; with ₹3 per share payable on application, how much is adjusted towards allotment?",
    answer: "The excess application money is 5,000 × ₹3 = ₹15,000, which is adjusted towards allotment at ₹1.50 per share allotted (₹15,000 ÷ 10,000). The ratio of shares applied to shares allotted is 3:2." },
  { id: 'v12-130', topicId: 'share-capital', options: ['fsa', 'computerised'], difficulty: 'easy',
    question: "What happens when an issue is under-subscribed?",
    answer: "All applicants get the shares they applied for, provided the minimum subscription has been received. Otherwise the allotment cannot be made and the money is refunded." },
  { id: 'v12-131', topicId: 'share-capital', options: ['fsa', 'computerised'], difficulty: 'easy',
    question: "What are calls in arrears?",
    answer: "They are amounts called up on shares but not paid by the shareholders by the due date. They are deducted from the subscribed capital in the note on share capital." },
  { id: 'v12-132', topicId: 'share-capital', options: ['fsa', 'computerised'], difficulty: 'medium',
    question: "What are calls in advance, and where are they shown?",
    answer: "They are amounts received from shareholders before the company has called them up. Until the call is made they are a liability, shown under current liabilities as other current liabilities." },
  { id: 'v12-133', topicId: 'share-capital', options: ['fsa', 'computerised'], difficulty: 'medium',
    question: "For what purposes can the Securities Premium be used?",
    answer: "Under Section 52 of the Companies Act, 2013, it can be used only to issue fully paid bonus shares, to write off preliminary expenses, to write off the expenses, commission or discount on an issue of shares or debentures, to provide for the premium payable on redemption of preference shares or debentures, and to buy back the company's own shares. It cannot be distributed as dividend." },
  { id: 'v12-134', topicId: 'share-capital', options: ['fsa', 'computerised'], difficulty: 'easy',
    question: "Can a company issue its shares at a discount?",
    answer: "No; under Section 53 of the Companies Act, 2013 a company cannot issue shares at a discount, except sweat equity shares." },
  { id: 'v12-135', topicId: 'share-capital', options: ['fsa', 'computerised'], difficulty: 'easy',
    question: "What is forfeiture of shares?",
    answer: "It is the cancellation of shares when a shareholder fails to pay the allotment or a call money. The shareholder loses the shares and the money already paid on them." },
  { id: 'v12-136', topicId: 'share-capital', options: ['fsa', 'computerised'], difficulty: 'medium',
    question: "What entry is passed on the forfeiture of shares?",
    answer: "Share Capital is debited with the amount called up on those shares, the unpaid allotment or calls account is credited with the amount not paid, and Share Forfeiture Account is credited with the amount already received." },
  { id: 'v12-137', topicId: 'share-capital', options: ['fsa', 'computerised'], difficulty: 'medium',
    question: "What is the limit on the discount when forfeited shares are reissued?",
    answer: "The discount on reissue cannot be more than the amount forfeited on those shares. It is debited to Share Forfeiture Account, and any balance left on the reissued shares is transferred to Capital Reserve." },
  { id: 'v12-138', topicId: 'share-capital', options: ['fsa', 'computerised'], difficulty: 'complex',
    question: "200 shares of ₹10 each on which ₹6 had been paid were forfeited and reissued as fully paid at ₹8 each; how much goes to Capital Reserve?",
    answer: "The amount forfeited is 200 × ₹6 = ₹1,200 and the discount on reissue is 200 × ₹2 = ₹400. The balance of ₹800 is transferred to Capital Reserve." },
  { id: 'v12-139', topicId: 'share-capital', options: ['fsa', 'computerised'], difficulty: 'easy',
    question: "Where is the balance of Share Forfeiture Account shown in the balance sheet?",
    answer: "Until the shares are reissued it is added to the paid-up capital in the note on share capital, under shareholders' funds." },
  { id: 'v12-140', topicId: 'share-capital', options: ['fsa', 'computerised'], difficulty: 'easy',
    question: "What is a private placement of shares?",
    answer: "It is an issue of securities to a selected group of persons, not to the public, through a private placement offer letter, under Section 42 of the Companies Act, 2013. In a financial year the offer can be made to at most 200 persons, not counting qualified institutional buyers and employees offered shares under ESOP." },
  { id: 'v12-141', topicId: 'share-capital', options: ['fsa', 'computerised'], difficulty: 'easy',
    question: "What is an Employee Stock Option Plan?",
    answer: "It is a plan under which a company gives its employees, including whole-time directors, the option to buy its shares at a future date at a price fixed in advance, usually lower than the market price." },
  { id: 'v12-142', topicId: 'share-capital', options: ['fsa', 'computerised'], difficulty: 'medium',
    question: "A company buys assets for ₹2,20,000 and pays by issuing shares of ₹10 each at ₹11; how many shares are issued?",
    answer: "The number of shares is ₹2,20,000 ÷ ₹11 = 20,000. Share Capital is credited with ₹2,00,000 and Securities Premium with ₹20,000." },
  // -------------------------------------------------------------------------------------------------------------
  // Debentures.
  // -------------------------------------------------------------------------------------------------------------
  { id: 'v12-143', topicId: 'debentures', options: ['fsa', 'computerised'], difficulty: 'easy',
    question: "What is a debenture?",
    answer: "It is a written acknowledgement of a debt issued by a company, carrying interest at a fixed rate and repayable on stated terms. A debenture holder is a creditor of the company, not an owner." },
  { id: 'v12-144', topicId: 'debentures', options: ['fsa', 'computerised'], difficulty: 'easy',
    question: "How do debentures differ from shares?",
    answer: "A shareholder is an owner who gets a dividend out of profit and has voting rights. A debenture holder is a creditor who gets interest at a fixed rate, which is a charge against profit paid whether or not there is a profit, and has no voting rights." },
  { id: 'v12-145', topicId: 'debentures', options: ['fsa', 'computerised'], difficulty: 'easy',
    question: "What is the difference between secured and unsecured debentures?",
    answer: "Secured debentures carry a charge on the company's assets, so the holders can recover their money from those assets if the company defaults. Unsecured debentures carry no such charge." },
  { id: 'v12-146', topicId: 'debentures', options: ['fsa', 'computerised'], difficulty: 'easy',
    question: "What are convertible debentures?",
    answer: "They are debentures that can be converted into equity shares after a stated period, on the terms fixed at issue. Non-convertible debentures cannot be converted and are repaid in cash." },
  { id: 'v12-147', topicId: 'debentures', options: ['fsa', 'computerised'], difficulty: 'medium',
    question: "What is meant by issuing debentures as collateral security?",
    answer: "They are issued to a lender as additional security for a loan, and the lender can use them only if the loan is not repaid. The company may show them only as a note under the loan, or record them by debiting Debentures Suspense Account and crediting Debentures Account." },
  { id: 'v12-148', topicId: 'debentures', options: ['fsa', 'computerised'], difficulty: 'medium',
    question: "What is Loss on Issue of Debentures?",
    answer: "It is the total of the discount allowed on issue and the premium payable on redemption, recorded at the time of issue. The premium payable is credited to Premium on Redemption of Debentures Account, which is a liability." },
  { id: 'v12-149', topicId: 'debentures', options: ['fsa', 'computerised'], difficulty: 'complex',
    question: "1,000 debentures of ₹100 each are issued at a discount of 5% and are redeemable at a premium of 10%; what is the loss on issue?",
    answer: "The discount is ₹5,000 and the premium payable is ₹10,000, so the loss on issue is ₹15,000. It is written off first from Securities Premium, if any, and the rest from the Statement of Profit and Loss in the year of issue." },
  { id: 'v12-150', topicId: 'debentures', options: ['fsa', 'computerised'], difficulty: 'medium',
    question: "How is the discount or loss on issue of debentures written off?",
    answer: "It is written off first from the Securities Premium, if the company has one, and any remaining amount from the Statement of Profit and Loss, in the year the debentures are issued." },
  { id: 'v12-151', topicId: 'debentures', options: ['fsa', 'computerised'], difficulty: 'easy',
    question: "Is interest on debentures a charge or an appropriation of profit?",
    answer: "It is a charge against profit, payable at the fixed rate whether or not the company earns a profit. It is shown under finance costs in the Statement of Profit and Loss." },
  { id: 'v12-152', topicId: 'debentures', options: ['fsa', 'computerised'], difficulty: 'medium',
    question: "How are debentures issued to a vendor for an asset recorded?",
    answer: "On buying the asset, the asset is debited and the vendor credited. When the debentures are issued, the vendor is debited and Debentures Account credited, with Securities Premium credited if they are issued at a premium; the number issued is the amount payable divided by the issue price." },
  { id: 'v12-153', topicId: 'debentures', options: ['fsa', 'computerised'], difficulty: 'easy',
    question: "Where are debentures shown in a company's balance sheet?",
    answer: "Under non-current liabilities as long-term borrowings. The part repayable within twelve months of the balance sheet date is a current liability, shown under short-term borrowings as current maturities of long-term borrowings." },
  // -------------------------------------------------------------------------------------------------------------
  // Financial statements of a company.
  // -------------------------------------------------------------------------------------------------------------
  { id: 'v12-154', topicId: 'company-financial-statements', options: ['fsa'], difficulty: 'easy',
    question: "What do the financial statements of a company include under the Companies Act, 2013?",
    answer: "The balance sheet, the statement of profit and loss, the cash flow statement, the statement of changes in equity where it applies, and the notes that explain them." },
  { id: 'v12-155', topicId: 'company-financial-statements', options: ['fsa'], difficulty: 'easy',
    question: "What are the main heads of a company's balance sheet under Schedule III?",
    answer: "Equity and Liabilities has shareholders' funds, share application money pending allotment, non-current liabilities and current liabilities. Assets has non-current assets and current assets." },
  { id: 'v12-156', topicId: 'company-financial-statements', options: ['fsa'], difficulty: 'easy',
    question: "What are the sub-heads of shareholders' funds?",
    answer: "Share capital, reserves and surplus, and money received against share warrants." },
  { id: 'v12-157', topicId: 'company-financial-statements', options: ['fsa'], difficulty: 'easy',
    question: "What are the sub-heads of non-current liabilities and current liabilities?",
    answer: "Non-current liabilities are long-term borrowings, deferred tax liabilities (net), other long-term liabilities and long-term provisions. Current liabilities are short-term borrowings, trade payables, other current liabilities and short-term provisions." },
  { id: 'v12-158', topicId: 'company-financial-statements', options: ['fsa'], difficulty: 'easy',
    question: "What are the sub-heads of current assets?",
    answer: "Current investments, inventories, trade receivables, cash and cash equivalents, short-term loans and advances, and other current assets." },
  { id: 'v12-159', topicId: 'company-financial-statements', options: ['fsa'], difficulty: 'medium',
    question: "When is an asset classified as current?",
    answer: "When it is expected to be realised, sold or consumed within the company's operating cycle or within twelve months of the reporting date, is held mainly for trading, or is cash or a cash equivalent that is not restricted. All other assets are non-current." },
  { id: 'v12-160', topicId: 'company-financial-statements', options: ['fsa'], difficulty: 'easy',
    question: "What is the operating cycle?",
    answer: "It is the time between acquiring assets for processing and realising them in cash or cash equivalents. When it cannot be clearly identified, it is taken as twelve months." },
  { id: 'v12-161', topicId: 'company-financial-statements', options: ['fsa'], difficulty: 'medium',
    question: "Under which heads and sub-heads are loose tools, goodwill and a bank overdraft shown?",
    answer: "Loose tools go under current assets as inventories, and purchased goodwill under non-current assets as intangible assets within property, plant and equipment and intangible assets. A bank overdraft goes under current liabilities as short-term borrowings." },
  { id: 'v12-162', topicId: 'company-financial-statements', options: ['fsa'], difficulty: 'medium',
    question: "Under which sub-heads are unpaid dividend and provision for tax shown?",
    answer: "Unpaid dividend is shown under current liabilities as other current liabilities. Provision for tax is shown under current liabilities as short-term provisions." },
  { id: 'v12-163', topicId: 'company-financial-statements', options: ['fsa'], difficulty: 'easy',
    question: "How do current investments differ from non-current investments?",
    answer: "Current investments are those meant to be realised within twelve months of the reporting date. Investments meant to be held for longer are non-current investments." },
  { id: 'v12-164', topicId: 'company-financial-statements', options: ['fsa'], difficulty: 'easy',
    question: "Where are Capital Reserve and General Reserve shown?",
    answer: "Both are shown under shareholders' funds, in the sub-head reserves and surplus." },
  { id: 'v12-165', topicId: 'company-financial-statements', options: ['fsa'], difficulty: 'medium',
    question: "What is the format of the Statement of Profit and Loss?",
    answer: "Revenue from operations and other income make up total income. The expenses (cost of materials consumed, purchases of stock-in-trade, changes in inventories, employee benefits expense, finance costs, depreciation and amortisation, and other expenses) are deducted to give profit before tax, and tax is deducted to give profit for the period." },
  { id: 'v12-166', topicId: 'company-financial-statements', options: ['fsa'], difficulty: 'medium',
    question: "What is the difference between revenue from operations and other income?",
    answer: "Revenue from operations is income from the company's main business, such as the sale of its products or services. Other income comes from outside the main business, such as interest and dividends received or profit on the sale of an investment, for a non-financial company." },
  { id: 'v12-167', topicId: 'company-financial-statements', options: ['fsa'], difficulty: 'complex',
    question: "Where is a debit balance in the Statement of Profit and Loss shown in the balance sheet?",
    answer: "It is shown as a negative figure under reserves and surplus, in the surplus, even if this makes the total of reserves and surplus negative. It is not shown as an asset." },
  { id: 'v12-168', topicId: 'company-financial-statements', options: ['fsa'], difficulty: 'medium',
    question: "Why are notes to accounts given with the financial statements?",
    answer: "The face of the balance sheet and the statement of profit and loss shows only totals, and the notes give the details behind them, such as the classes of share capital or the breakup of borrowings. They also state the accounting policies, which a reader needs to understand the figures." },
  { id: 'v12-169', topicId: 'company-financial-statements', options: ['fsa'], difficulty: 'complex',
    question: "What are the limitations of a company's financial statements?",
    answer: "They are based on historical cost and ignore changes in price levels, leave out qualitative matters such as the skill of management, and contain estimates such as depreciation. So they are reports on a continuing business, not an exact measure of its worth." },
  // -------------------------------------------------------------------------------------------------------------
  // Financial statement analysis.
  // -------------------------------------------------------------------------------------------------------------
  { id: 'v12-170', topicId: 'financial-statement-analysis', options: ['fsa'], difficulty: 'easy',
    question: "What is financial statement analysis?",
    answer: "It is the study of the relationships among the items in financial statements, across years or within a year, to judge a company's profitability, liquidity, solvency and efficiency." },
  { id: 'v12-171', topicId: 'financial-statement-analysis', options: ['fsa'], difficulty: 'easy',
    question: "What are the objectives of financial statement analysis?",
    answer: "To judge the company's earning capacity and profitability, its ability to pay short-term and long-term debts, the efficiency with which it uses its assets, and its prospects for growth. It also allows comparison with past years and with other companies." },
  { id: 'v12-172', topicId: 'financial-statement-analysis', options: ['fsa'], difficulty: 'medium',
    question: "Why is financial statement analysis useful to different users?",
    answer: "Shareholders judge profitability and growth, trade creditors judge liquidity, and lenders judge solvency and the safety of interest. Management uses it to plan and control, and the government uses it for policy and taxation." },
  { id: 'v12-173', topicId: 'financial-statement-analysis', options: ['fsa'], difficulty: 'medium',
    question: "What are the limitations of financial statement analysis?",
    answer: "It rests on historical figures that ignore price-level changes, it cannot measure qualitative factors, and differences in accounting policies make comparison between companies difficult. The results are only as good as the statements, and window dressing can distort them." },
  { id: 'v12-174', topicId: 'financial-statement-analysis', options: ['fsa'], difficulty: 'easy',
    question: "What are the tools of financial statement analysis?",
    answer: "Comparative statements, common size statements, trend analysis, accounting ratios and the cash flow statement." },
  { id: 'v12-175', topicId: 'financial-statement-analysis', options: ['fsa'], difficulty: 'medium',
    question: "What is the difference between horizontal and vertical analysis?",
    answer: "Horizontal analysis compares an item over two or more years, as in comparative statements and trend analysis. Vertical analysis compares the items of one year's statement with a common base, as in common size statements." },
  { id: 'v12-176', topicId: 'financial-statement-analysis', options: ['fsa'], difficulty: 'easy',
    question: "What is a comparative statement?",
    answer: "It shows the figures of two or more years side by side, with the absolute change and the percentage change in each item, so that the direction and size of changes are clear." },
  { id: 'v12-177', topicId: 'financial-statement-analysis', options: ['fsa'], difficulty: 'easy',
    question: "What is a common size statement?",
    answer: "It expresses each item of a statement as a percentage of a common base: total assets (or total equity and liabilities) for the balance sheet, and revenue from operations for the statement of profit and loss." },
  { id: 'v12-178', topicId: 'financial-statement-analysis', options: ['fsa'], difficulty: 'medium',
    question: "Why are the common size percentages of a balance sheet worked on total assets?",
    answer: "Total assets equal the total of equity and liabilities, so one base serves both sides. Each asset then shows its share of what the company owns, and each source shows its share of how the assets are financed, on the same base for both years." },
  { id: 'v12-179', topicId: 'financial-statement-analysis', options: ['fsa'], difficulty: 'medium',
    question: "Why is revenue from operations the base for a common size statement of profit and loss?",
    answer: "Every expense is incurred to earn revenue, so expressing each item as a share of revenue shows how much of every ₹100 of sales goes on each cost and how much is left as profit. It also makes years of different size comparable." },
  { id: 'v12-180', topicId: 'financial-statement-analysis', options: ['fsa'], difficulty: 'medium',
    question: "Trade receivables rose from ₹80 lakh to ₹100 lakh; what is the percentage change, and why is last year the base?",
    answer: "The change is ₹20 lakh, which is 20 ÷ 80 × 100 = 25% of last year's figure. Last year is the base because the question is how much the item has grown from where it was." },
  { id: 'v12-181', topicId: 'financial-statement-analysis', options: ['fsa'], difficulty: 'complex',
    question: "Revenue from operations grew by 20% but the cost of materials grew by 30%; what does it show?",
    answer: "Costs rose faster than revenue, so the gross margin has narrowed. The company may be facing higher input prices that it could not pass on to customers, which needs a closer look." },
  { id: 'v12-182', topicId: 'financial-statement-analysis', options: ['fsa'], difficulty: 'complex',
    question: "In a common size statement, employee benefits expense rose from 12% to 15% of revenue; what does that mean?",
    answer: "Out of every ₹100 of revenue the company now spends ₹15 on employees instead of ₹12, so staff costs grew faster than sales. Unless revenue picks up, this squeezes the operating profit margin by about 3 percentage points." },
  { id: 'v12-183', topicId: 'financial-statement-analysis', options: ['fsa'], difficulty: 'complex',
    question: "Can an item rise in rupees but fall as a common size percentage?",
    answer: "Yes, when revenue grows faster than the item. For example, expenses that rise from ₹40 lakh to ₹45 lakh are 40% of a revenue of ₹100 lakh but only 37.5% of a revenue of ₹120 lakh." },
  { id: 'v12-184', topicId: 'financial-statement-analysis', options: ['fsa'], difficulty: 'easy',
    question: "What is trend analysis?",
    answer: "It expresses the figures of several years as percentages of a base year's figures, taken as 100, to show the direction in which each item is moving." },
  { id: 'v12-185', topicId: 'financial-statement-analysis', options: ['fsa'], difficulty: 'complex',
    question: "What is window dressing, and why does it limit analysis?",
    answer: "Window dressing is presenting the statements so that the position looks better than it is, for example by postponing purchases until after the year-end to show a higher cash balance. It limits analysis because the year-end figures may not represent the rest of the year." },
  { id: 'v12-186', topicId: 'financial-statement-analysis', options: ['fsa'], difficulty: 'medium',
    question: "Why is it not enough to look at the comparative statement alone?",
    answer: "A comparative statement shows how much each item changed but not how important it is in the whole. A common size statement or ratios are needed to see whether a change matters, since a 50% rise in a tiny item can mean less than a 5% rise in a large one." },
  // -------------------------------------------------------------------------------------------------------------
  // Accounting ratios.
  // -------------------------------------------------------------------------------------------------------------
  { id: 'v12-187', topicId: 'accounting-ratios', options: ['fsa'], difficulty: 'easy',
    question: "What is an accounting ratio?",
    answer: "It is a mathematical relationship between two related figures in the financial statements, expressed as a pure ratio, as times, or as a percentage." },
  { id: 'v12-188', topicId: 'accounting-ratios', options: ['fsa'], difficulty: 'easy',
    question: "How are accounting ratios classified?",
    answer: "Into liquidity ratios, solvency ratios, activity (turnover) ratios and profitability ratios." },
  { id: 'v12-189', topicId: 'accounting-ratios', options: ['fsa'], difficulty: 'easy',
    question: "How is the current ratio calculated, and what is the usual norm?",
    answer: "Current ratio is current assets divided by current liabilities. A ratio of 2:1 is often taken as comfortable, though the right level depends on the industry." },
  { id: 'v12-190', topicId: 'accounting-ratios', options: ['fsa'], difficulty: 'complex',
    question: "What does a current ratio of 0.8:1 tell you?",
    answer: "Current liabilities are more than current assets, so the company may struggle to pay its short-term debts unless it has quick cash inflows or ready credit. Before judging, I would compare it with the industry and with past years, since some businesses that sell for cash work safely with low ratios." },
  { id: 'v12-191', topicId: 'accounting-ratios', options: ['fsa'], difficulty: 'complex',
    question: "Does a high current ratio always mean the company is in good shape?",
    answer: "No; a very high ratio may come from idle cash, slow-moving inventory or receivables that are not being collected, all of which earn nothing. It shows safety for creditors but may also show poor use of funds." },
  { id: 'v12-192', topicId: 'accounting-ratios', options: ['fsa'], difficulty: 'easy',
    question: "How is the quick ratio calculated?",
    answer: "Quick ratio is quick assets divided by current liabilities, where quick assets are current assets less inventories and prepaid expenses. A ratio of 1:1 is usually taken as satisfactory." },
  { id: 'v12-193', topicId: 'accounting-ratios', options: ['fsa'], difficulty: 'medium',
    question: "Why is the quick ratio a sharper test of liquidity than the current ratio?",
    answer: "It leaves out inventories, which must first be sold and may take time or sell below value, and prepaid expenses, which cannot be turned into cash at all. So it shows whether the company can meet its current liabilities from assets that become cash quickly." },
  { id: 'v12-194', topicId: 'accounting-ratios', options: ['fsa'], difficulty: 'medium',
    question: "Current assets are ₹3,00,000, including inventories of ₹80,000 and prepaid expenses of ₹10,000, and current liabilities are ₹1,40,000; what is the quick ratio?",
    answer: "Quick assets are ₹3,00,000 − ₹80,000 − ₹10,000 = ₹2,10,000, so the quick ratio is ₹2,10,000 ÷ ₹1,40,000 = 1.5:1, that is 3:2." },
  { id: 'v12-195', topicId: 'accounting-ratios', options: ['fsa'], difficulty: 'complex',
    question: "What happens to the current ratio when a bill payable is paid?",
    answer: "Current assets and current liabilities fall by the same amount, so a ratio above 1:1 rises, a ratio below 1:1 falls, and a ratio of exactly 1:1 stays the same. For example, ₹2,00,000 ÷ ₹1,00,000 = 2:1 becomes ₹1,80,000 ÷ ₹80,000 = 2.25:1 after paying a bill of ₹20,000." },
  { id: 'v12-196', topicId: 'accounting-ratios', options: ['fsa'], difficulty: 'complex',
    question: "What is the effect of buying inventory on credit on the current ratio and the quick ratio?",
    answer: "Current assets and current liabilities rise by the same amount, so a current ratio above 1:1 falls and one below 1:1 rises. Quick assets do not change while current liabilities rise, so the quick ratio falls." },
  { id: 'v12-197', topicId: 'accounting-ratios', options: ['fsa'], difficulty: 'easy',
    question: "How is the debt-equity ratio calculated?",
    answer: "It is long-term debt divided by shareholders' funds (equity). Long-term debt means long-term borrowings and long-term provisions, and shareholders' funds are share capital plus reserves and surplus." },
  { id: 'v12-198', topicId: 'accounting-ratios', options: ['fsa'], difficulty: 'medium',
    question: "What does a high debt-equity ratio indicate?",
    answer: "The company depends more on borrowed funds than on owners' funds, so its financial risk is higher, because interest and repayments must be met whether or not it earns a profit. A ratio up to 2:1 is generally taken as safe." },
  { id: 'v12-199', topicId: 'accounting-ratios', options: ['fsa'], difficulty: 'medium',
    question: "Long-term borrowings are ₹6,00,000 and shareholders' funds are ₹12,00,000; what is the debt-equity ratio?",
    answer: "It is ₹6,00,000 ÷ ₹12,00,000 = 0.5:1, that is 1:2, so the owners provide twice as much long-term finance as the lenders." },
  { id: 'v12-200', topicId: 'accounting-ratios', options: ['fsa'], difficulty: 'complex',
    question: "What is the effect on the debt-equity ratio of issuing equity shares for cash, and of issuing debentures for cash?",
    answer: "Issuing shares raises shareholders' funds while long-term debt is unchanged, so the ratio falls. Issuing debentures raises long-term debt, so the ratio rises." },
  { id: 'v12-201', topicId: 'accounting-ratios', options: ['fsa'], difficulty: 'easy',
    question: "What is the total assets to debt ratio, and what does a higher figure mean?",
    answer: "It is total assets divided by long-term debt. A higher ratio means more assets cover each rupee of long-term debt, so lenders are safer." },
  { id: 'v12-202', topicId: 'accounting-ratios', options: ['fsa'], difficulty: 'medium',
    question: "What does the proprietary ratio show?",
    answer: "It is shareholders' funds divided by total assets, and shows the share of the assets financed by the owners. A higher ratio means less dependence on outside funds and more safety for creditors." },
  { id: 'v12-203', topicId: 'accounting-ratios', options: ['fsa'], difficulty: 'medium',
    question: "What is the interest coverage ratio, and what does a ratio of 10 times mean?",
    answer: "It is net profit before interest and tax divided by interest on long-term debt; for example, ₹5,00,000 ÷ ₹50,000 = 10 times. It means the profit available covers the interest ten times over, so lenders can be confident of their interest." },
  { id: 'v12-204', topicId: 'accounting-ratios', options: ['fsa'], difficulty: 'easy',
    question: "How is the inventory turnover ratio calculated?",
    answer: "It is the cost of revenue from operations divided by the average inventory, where average inventory is the opening plus the closing inventory divided by two." },
  { id: 'v12-205', topicId: 'accounting-ratios', options: ['fsa'], difficulty: 'easy',
    question: "How is the cost of revenue from operations found?",
    answer: "It is opening inventory plus net purchases plus direct expenses, less closing inventory. It can also be found as revenue from operations less gross profit." },
  { id: 'v12-206', topicId: 'accounting-ratios', options: ['fsa'], difficulty: 'medium',
    question: "Why is the average inventory used in the inventory turnover ratio rather than the closing inventory?",
    answer: "Inventory changes during the year, while the cost of revenue covers the whole year. The average of the opening and closing figures is a fairer measure of the inventory held while that cost was incurred." },
  { id: 'v12-207', topicId: 'accounting-ratios', options: ['fsa'], difficulty: 'complex',
    question: "What does a falling inventory turnover ratio suggest?",
    answer: "Inventory is selling more slowly than before, which may point to falling demand, overstocking or obsolete goods, and it ties up more money in stock. I would check whether sales fell or inventory was built up on purpose, for example ahead of a festive season." },
  { id: 'v12-208', topicId: 'accounting-ratios', options: ['fsa'], difficulty: 'medium',
    question: "How is the trade receivables turnover ratio calculated, and what is the average collection period?",
    answer: "It is credit revenue from operations divided by average trade receivables, which include debtors and bills receivable. The average collection period is 365 days divided by the ratio, so a ratio of 8 times means about 46 days." },
  { id: 'v12-209', topicId: 'accounting-ratios', options: ['fsa'], difficulty: 'medium',
    question: "What does the trade payables turnover ratio show?",
    answer: "It is net credit purchases divided by average trade payables (creditors and bills payable), and shows how quickly the company pays its suppliers. A high ratio means prompt payment, while a low ratio means longer credit from suppliers or delayed payments." },
  { id: 'v12-210', topicId: 'accounting-ratios', options: ['fsa'], difficulty: 'medium',
    question: "What is the working capital turnover ratio, and what does a higher figure show?",
    answer: "It is revenue from operations divided by working capital, which is current assets less current liabilities. A higher ratio shows more sales earned from each rupee of working capital, so it is used efficiently, though a very high ratio may mean too little working capital." },
  { id: 'v12-211', topicId: 'accounting-ratios', options: ['fsa'], difficulty: 'medium',
    question: "Revenue from operations is ₹10,00,000 and the cost of revenue from operations is ₹7,50,000; what is the gross profit ratio?",
    answer: "Gross profit is ₹2,50,000, so the gross profit ratio is ₹2,50,000 ÷ ₹10,00,000 × 100 = 25%." },
  { id: 'v12-212', topicId: 'accounting-ratios', options: ['fsa'], difficulty: 'medium',
    question: "How are the operating ratio and the operating profit ratio related?",
    answer: "The operating ratio is the cost of revenue from operations plus operating expenses, as a percentage of revenue from operations, and the operating profit ratio is 100 minus the operating ratio. So an operating ratio of 85% means an operating profit ratio of 15%." },
  { id: 'v12-213', topicId: 'accounting-ratios', options: ['fsa'], difficulty: 'easy',
    question: "How is the net profit ratio calculated?",
    answer: "It is net profit divided by revenue from operations, multiplied by 100. It shows how much of each ₹100 of revenue is left as profit after all expenses." },
  { id: 'v12-214', topicId: 'accounting-ratios', options: ['fsa'], difficulty: 'complex',
    question: "The gross profit ratio rose but the net profit ratio fell; what could explain it?",
    answer: "The company earned more on its trading, but its other expenses, such as employee costs, finance costs or depreciation, grew faster than its revenue. I would look at the common size statement of profit and loss to find which expense rose." },
  { id: 'v12-215', topicId: 'accounting-ratios', options: ['fsa'], difficulty: 'medium',
    question: "How is return on investment calculated, and what is capital employed?",
    answer: "Return on investment is profit before interest and tax divided by capital employed, multiplied by 100. Capital employed is shareholders' funds plus non-current liabilities, or equally non-current assets plus working capital." },
  { id: 'v12-216', topicId: 'accounting-ratios', options: ['fsa'], difficulty: 'complex',
    question: "Shareholders' funds are ₹8,00,000, non-current liabilities ₹2,00,000 and profit before interest and tax ₹1,50,000; what is the return on investment?",
    answer: "Capital employed is ₹10,00,000, so the return on investment is ₹1,50,000 ÷ ₹10,00,000 × 100 = 15%." },
  { id: 'v12-217', topicId: 'accounting-ratios', options: ['fsa'], difficulty: 'complex',
    question: "Why is return on investment worked on profit before interest and tax?",
    answer: "Capital employed includes both the owners' funds and long-term debt, so the return must be measured before interest, which is the reward to the lenders, and before tax. This shows how well the whole of the capital is used, whatever the mix of finance or the tax rate." },
  { id: 'v12-218', topicId: 'accounting-ratios', options: ['fsa'], difficulty: 'medium',
    question: "What is the main limitation of ratio analysis?",
    answer: "A ratio is only as reliable as the figures behind it, and those figures are historical, ignore price-level changes and qualitative factors, and depend on accounting policies. So a ratio means little alone and must be compared with past years, the industry or a competitor." },
  { id: 'v12-219', topicId: 'accounting-ratios', options: ['fsa'], difficulty: 'easy',
    question: "Which ratios measure liquidity and which measure solvency?",
    answer: "Liquidity is measured by the current ratio and the quick ratio. Solvency is measured by the debt-equity, total assets to debt, proprietary and interest coverage ratios." },
  // -------------------------------------------------------------------------------------------------------------
  // Cash flow statement.
  // -------------------------------------------------------------------------------------------------------------
  { id: 'v12-220', topicId: 'cash-flow-statement', options: ['fsa'], difficulty: 'easy',
    question: "What is a cash flow statement?",
    answer: "It is a statement that shows the inflows and outflows of cash and cash equivalents during a period, classified into operating, investing and financing activities." },
  { id: 'v12-221', topicId: 'cash-flow-statement', options: ['fsa'], difficulty: 'easy',
    question: "Which accounting standard governs the cash flow statement?",
    answer: "AS 3 (Revised), Cash Flow Statements, issued by the Institute of Chartered Accountants of India." },
  { id: 'v12-222', topicId: 'cash-flow-statement', options: ['fsa'], difficulty: 'easy',
    question: "What are operating, investing and financing activities?",
    answer: "Operating activities are the main revenue-earning activities of the company. Investing activities are the purchase and sale of long-term assets and investments, and financing activities change the size and make-up of its owners' funds and borrowings." },
  { id: 'v12-223', topicId: 'cash-flow-statement', options: ['fsa'], difficulty: 'easy',
    question: "What are cash equivalents?",
    answer: "They are short-term, highly liquid investments that can be readily converted into known amounts of cash and carry an insignificant risk of change in value. An investment usually qualifies only if it matures within three months of the date it was acquired." },
  { id: 'v12-224', topicId: 'cash-flow-statement', options: ['fsa'], difficulty: 'medium',
    question: "How is a bank overdraft treated in the cash flow statement?",
    answer: "A bank overdraft or cash credit is treated as a short-term borrowing, so an increase or decrease in it is shown under financing activities. It is not part of cash and cash equivalents." },
  { id: 'v12-225', topicId: 'cash-flow-statement', options: ['fsa'], difficulty: 'medium',
    question: "Why is interest paid a financing activity for a non-financial company?",
    answer: "Interest is the cost of obtaining borrowed funds, so it belongs with the borrowing itself under financing activities. It has nothing to do with the company's main trading or manufacturing operations." },
  { id: 'v12-226', topicId: 'cash-flow-statement', options: ['fsa'], difficulty: 'medium',
    question: "Under which activity are interest received and dividends received shown for a non-financial company?",
    answer: "Under investing activities, because they are returns on the company's investments. Dividends paid, like interest paid, are financing activities." },
  { id: 'v12-227', topicId: 'cash-flow-statement', options: ['fsa'], difficulty: 'complex',
    question: "How do interest and dividends received and paid differ for a financial enterprise?",
    answer: "For a bank or finance company, lending and investing are its main business, so interest paid and interest and dividends received are operating activities. Dividends paid remain a financing activity." },
  { id: 'v12-228', topicId: 'cash-flow-statement', options: ['fsa'], difficulty: 'complex',
    question: "Is depreciation a source of cash?",
    answer: "No; depreciation is a non-cash expense that reduces profit without any cash going out, so it is added back to net profit to find the cash from operations. The cash itself comes from revenue, not from depreciation." },
  { id: 'v12-229', topicId: 'cash-flow-statement', options: ['fsa'], difficulty: 'medium',
    question: "What are the steps in finding cash from operating activities by the indirect method?",
    answer: "Start from net profit before tax and add back non-cash and non-operating expenses such as depreciation and finance costs, and deduct non-operating incomes such as profit on sale of assets. Then adjust for changes in current assets and current liabilities, and deduct the income tax paid." },
  { id: 'v12-230', topicId: 'cash-flow-statement', options: ['fsa'], difficulty: 'medium',
    question: "Why does the indirect method start from net profit before tax?",
    answer: "The tax actually paid in cash may differ from the tax charged in the statement of profit and loss. So the cash flow starts before tax, and the tax paid is deducted separately at the end of operating activities." },
  { id: 'v12-231', topicId: 'cash-flow-statement', options: ['fsa'], difficulty: 'medium',
    question: "Why is an increase in trade receivables deducted in operating activities?",
    answer: "The sales were counted in profit, but part of the money has not yet been received, so cash is less than profit by the increase. An increase in trade payables is added for the opposite reason: expenses were charged but not yet paid." },
  { id: 'v12-232', topicId: 'cash-flow-statement', options: ['fsa'], difficulty: 'complex',
    question: "A machine with a book value of ₹40,000 is sold for ₹50,000; how is it shown in the cash flow statement?",
    answer: "The profit of ₹10,000 is deducted from net profit in operating activities because it is not from operations. The full sale proceeds of ₹50,000 are shown as an inflow under investing activities." },
  { id: 'v12-233', topicId: 'cash-flow-statement', options: ['fsa'], difficulty: 'complex',
    question: "Net profit before tax is ₹2,00,000, depreciation ₹30,000, inventories rose by ₹20,000, trade payables rose by ₹15,000 and tax paid is ₹50,000; what is the cash from operating activities?",
    answer: "Cash generated from operations is ₹2,00,000 + ₹30,000 − ₹20,000 + ₹15,000 = ₹2,25,000. After deducting tax paid of ₹50,000, the net cash from operating activities is ₹1,75,000." },
  { id: 'v12-234', topicId: 'cash-flow-statement', options: ['fsa'], difficulty: 'easy',
    question: "Under which activities are the purchase of machinery and the issue of shares for cash shown?",
    answer: "The purchase of machinery is an outflow under investing activities. The issue of shares for cash is an inflow under financing activities." },
  { id: 'v12-235', topicId: 'cash-flow-statement', options: ['fsa'], difficulty: 'complex',
    question: "Cash is used to buy marketable securities that mature in two months; is this a cash flow?",
    answer: "No; the securities are cash equivalents, so the purchase only changes one form of cash into another. Movements within cash and cash equivalents are not cash flows." },
  { id: 'v12-236', topicId: 'cash-flow-statement', options: ['fsa'], difficulty: 'medium',
    question: "Why is a cash flow statement useful when the company already has a statement of profit and loss?",
    answer: "Profit is worked on the accrual basis and includes non-cash items, so a profitable company can still be short of cash. The cash flow statement shows where cash actually came from and went, and whether operations generate enough cash to pay debts and fund growth." },
  { id: 'v12-237', topicId: 'cash-flow-statement', options: ['fsa'], difficulty: 'medium',
    question: "What are the limitations of a cash flow statement?",
    answer: "It shows only cash movements, so non-cash transactions such as issuing shares to a vendor for an asset are left out. It is not a substitute for the statement of profit and loss, because cash flow is not the same as profit." },
  { id: 'v12-238', topicId: 'cash-flow-statement', options: ['fsa'], difficulty: 'complex',
    question: "A company shows a good profit but negative cash from operating activities; what might explain it?",
    answer: "Its profit may be tied up in working capital, for example large credit sales not yet collected or a build-up of inventory. If this goes on, the company will have to borrow to pay its bills, so I would check the changes in trade receivables and inventories." },
  { id: 'v12-239', topicId: 'cash-flow-statement', options: ['fsa'], difficulty: 'easy',
    question: "Is the income tax paid shown under operating activities?",
    answer: "Yes; income tax paid is shown under operating activities unless it can be specifically identified with investing or financing activities." },
  // -------------------------------------------------------------------------------------------------------------
  // Computerised Accounting (the Part B option): the topic itself.
  // -------------------------------------------------------------------------------------------------------------
  { id: 'v12-240', topicId: 'computerised-accounting', options: ['computerised'], difficulty: 'easy',
    question: "What is a computerised accounting system?",
    answer: "It is a system that records business transactions and produces the books and reports with the help of a computer and accounting software. The accountant enters each transaction once as a voucher, and the software posts it, balances the accounts and prepares the trial balance and the financial statements." },
  { id: 'v12-241', topicId: 'computerised-accounting', options: ['computerised'], difficulty: 'easy',
    question: "What are three features of a computerised accounting system?",
    answer: "Speed, accuracy and reliability are three: once a transaction is entered, the software posts and totals it at once and without arithmetical errors. It also keeps the records up to date, so reports can be drawn at any moment." },
  { id: 'v12-242', topicId: 'computerised-accounting', options: ['computerised'], difficulty: 'medium',
    question: "What is the difference between generic, specific and tailored accounting software?",
    answer: "Generic software is ready-made for most small businesses and used as it is; specific software is made for a particular kind of business and adjusted to its needs; tailored software is built for one organisation's own requirements, usually a large one." },
  { id: 'v12-243', topicId: 'computerised-accounting', options: ['computerised'], difficulty: 'medium',
    question: "What is codification of accounts, and why is it needed?",
    answer: "It is giving every account head a code that shows its place in the hierarchy of groups, sub-groups and ledgers. Codes make data entry quicker and less error-prone, and let the software group accounts correctly in the reports." },
  { id: 'v12-244', topicId: 'computerised-accounting', options: ['computerised'], difficulty: 'easy',
    question: "What is data validation?",
    answer: "It is the check the software makes on data as it is entered, so that only data of the right kind and within sensible limits is accepted; for example, a date must be a valid date and an amount cannot be negative." },
  { id: 'v12-245', topicId: 'computerised-accounting', options: ['computerised'], difficulty: 'medium',
    question: "How is verification different from validation?",
    answer: "Validation checks that the data entered is acceptable in form, while verification checks that it agrees with the source document, for example by comparing the voucher on screen with the bill. Valid data can still be wrong if it was copied wrongly, which verification catches." },
  { id: 'v12-246', topicId: 'computerised-accounting', options: ['computerised'], difficulty: 'medium',
    question: "What is the difference between a relative and an absolute cell reference?",
    answer: "A relative reference such as B2 changes when the formula is copied, so it points to the cell in the same position relative to the new cell; an absolute reference such as $B$2 stays fixed. A rate kept in one cell is referred to absolutely so that every copied formula uses it." },
  { id: 'v12-247', topicId: 'computerised-accounting', options: ['computerised'], difficulty: 'medium',
    question: "Which spreadsheet functions work out depreciation, and how do they differ?",
    answer: "SLN gives the straight line depreciation, the same every year: (cost − salvage) ÷ life. DB gives depreciation on the written down value at a fixed rate the function works out from the cost, the salvage and the life, so the charge falls every year." },
  { id: 'v12-248', topicId: 'computerised-accounting', options: ['computerised'], difficulty: 'complex',
    question: "In a loan repayment schedule, why does the interest part of each instalment fall over time?",
    answer: "Each equal instalment (given by the PMT function) first pays the interest on the balance still owed, and the rest repays the loan. As the balance falls, the interest on it falls, so a larger part of each later instalment goes to repaying the principal." },
  { id: 'v12-249', topicId: 'computerised-accounting', options: ['computerised'], difficulty: 'medium',
    question: "Which security features does a computerised accounting system offer?",
    answer: "Passwords, which let only authorised users in and can limit each user to certain work, and regular backups, which allow the data to be restored if it is lost or damaged. Many packages also keep an audit trail of who changed what." },
];

